python3 << 'EOF'
import json

with open('batches/batch_0050.json', encoding='utf-8') as f:
    data = json.load(f)

def try_fix(s):
    if not s:
        return s
    try:
        b = s.encode('latin1')
    except UnicodeEncodeError:
        return s  # already proper unicode (contains chars outside latin1), leave as-is
    for enc in ('utf-8','cp932','euc_jp'):
        try:
            fixed = b.decode(enc)
            # heuristic: if result contains japanese chars or looks better, use it
            return fixed
        except Exception:
            continue
    # fallback: utf-8 with errors replace/ignore (for truncated multibyte at end)
    try:
        return b.decode('utf-8', errors='replace')
    except Exception:
        return s

out = []
for item in data:
    fixed_title = try_fix(item.get('title',''))
    fixed_desc = try_fix(item.get('desc',''))
    fixed_body = try_fix(item.get('body',''))
    out.append({
        'idx': item['idx'],
        'name': item['name'],
        'url': item['url'],
        'ok': item['ok'],
        'title': fixed_title,
        'desc': fixed_desc,
        'body': fixed_body,
    })

with open('/private/tmp/claude-501/-Users-rina--claude/bcb2f2c2-3bd5-40de-a21c-025da566713f/scratchpad/batch_0050_fixed.json','w',encoding='utf-8') as f:
    json.dump(out, f, ensure_ascii=False, indent=1)

print("done", len(out))
